css:
/* Service pricing: one card per service (name, inspection, description) with a price row per vehicle class.
   Every card and price comes from the `services` prop (one repeated card, one repeated price). */
.bz-section[data-bz-node="spr"]{background:#fff;padding-block:clamp(56px,6vw,96px)}
[data-bz-node="spr"] .bz-block{padding-block:0 var(--space-3)}
[data-bz-node="spr-h"] h2{margin-bottom:var(--space-5)}
[data-bz-node="spr-cards"]{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
[data-bz-node="spr-cards"]>.bz-col{grid-column:auto;background:#fff;border:1px solid var(--line);border-top:4px solid var(--accent);padding:clamp(22px,2.4vw,32px);display:flex;flex-direction:column}
[data-bz-node^="spr-name"] h3{font:700 clamp(1rem,1.5vw,1.25rem)/1.2 var(--font-heading);text-transform:uppercase;margin:0 0 4px}
[data-bz-node^="spr-sub"] .bz-text p{font:700 .6875rem/1.4 var(--font-body)!important;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)!important;margin:0 0 var(--space-3)!important}
[data-bz-node^="spr-desc"] .bz-text p{font-size:.8125rem!important;line-height:1.8;color:#4a4945!important;margin:0 0 var(--space-4)!important}
[data-bz-node^="spr-prices"]{margin-top:auto;grid-template-columns:minmax(0,1fr);gap:0;border-top:1px solid var(--line)}
[data-bz-node^="spr-prices"]>.bz-col{grid-column:auto;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:12px;align-items:baseline;padding:12px 0;border-bottom:1px solid var(--line)}
[data-bz-node^="spr-duty"]{grid-column:1;grid-row:1}
[data-bz-node^="spr-duty"] .bz-text p{font:700 .75rem/1.3 var(--font-body)!important;letter-spacing:.08em;text-transform:uppercase;color:var(--ink)!important;margin:0!important}
[data-bz-node^="spr-price-"]{grid-column:2;grid-row:1/span 2;text-align:right}
[data-bz-node^="spr-price-"] h4{font:800 1.5rem/1 var(--font-heading);color:var(--accent-dark);margin:0}
[data-bz-node^="spr-qts"]{grid-column:1;grid-row:2}
[data-bz-node^="spr-qts"] .bz-text p{font-size:.75rem!important;color:var(--muted)!important;margin:2px 0 0!important}
[data-bz-node^="spr-prices"] .bz-block{padding:0;min-width:0}
[data-bz-node^="spr-prices"] .bz-container{padding:0;max-width:none}
@media (max-width:1100px){[data-bz-node="spr-cards"]{grid-template-columns:minmax(0,1fr)}[data-bz-node="spr-cards"]>.bz-col{grid-column:1/-1}}
